"Abstand Anfang / Ende":"Etäisyys alku / loppu",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Alun / lopun etäisyys tekee laipasta osalaipan. Luonnoksen muut suljetut profiilit muuttuvat levyn leikkauksiksi. Reiät ja ikkunat laipassa: keskipiste reunaa pitkin (kaarevalla reunalla kaarta pitkin), keskipiste taivutuksen lopusta, koko – ne näkyvät myös avatussa muodossa. Jos kaareva reuna jatkuu taitteettomasti viereiseen reunaan ja molemmissa on laippa samalla taivutuskulmalla, laipat jatkuvat toisiinsa ilman vapautusleikkausta. „Ääriviiva luonnoksesta“ leikkaa luonnoksen suljetut profiilit laipasta: sen X kulkee reunaa pitkin, sen Y laippaan päin, nollapiste on reunan alussa taivutuksen lopussa (siirrettävissä).",
