"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Valitse kaikki pinnat, joiden pitää kadota (taskussa seinät ja pohja, reiässä seinämä, pyöristyksessä pyöristys). Viereiset pinnat jatketaan raon yli. Vaihe laskee uudelleen, kun kappaletta muutetaan; ensimmäisellä kerralla suuri geometriaydin latautuu sitä varten (muutama sekunti).",
