"Das Bild konnte nicht gelesen werden.":"Kuvaa ei voitu lukea.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Kuva on pohjana tasolla. Säädä koko, sijainti, kierto ja peittävyys sen jälkeen ominaisuusikkunassa (esim. leveys tunnetun mitan mukaan).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Geometriaytimen tulos on lukukelvoton",
"Das Ergebnis konnte nicht geschrieben werden":"Tulosta ei voitu kirjoittaa",
"Das Maß muss größer als 0 sein.":"Mitan on oltava suurempi kuin 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Verkko säilyy kolmioverkkona (ei B-Rep). Muokkaus kohdassa VERKKO: Korjaa, Vähennä, Tasoita, Tasoleikkaus … Valmistuksen 3D-jyrsintästrategiat voivat työstää sitä suoraan.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"Verkossa on {0} kolmiota. Jokaisesta tulee kappaleen pinta – se kestää kauan ja tekee kappaleesta hitaan. Ensin „Vähennä“ on yleensä parempi.\n\nMuunnetaanko silti?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"Verkko ei ole suljettu. Suorita ensin „Korjaa“ – kappale tarvitsee suljetun kuoren.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"Verkko ulottuu Z-suunnassa {0} … {1} mm, X-suunnassa {2} … {3} mm ja Y-suunnassa {4} … {5} mm. Pisteet, jotka poikkeavat suorasta toleranssia vähemmän, poistuvat.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profiili ei saa leikata akselia. Luonnoksen avoin viiva voi toimia akselina.",
"Das Profil mit den jetzigen Werten überschreiben":"Korvaa profiili nykyisillä arvoilla",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profiili viedään viivaa/murtoviivaa pitkin. Piirrä profiili mieluiten kohtisuoraan reitin alkuun nähden (esim. profiili XZ-tasolle, reitti XY-tasolle).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profiili kuvioidaan luonnostasosta kohotettuna tai upotettuna.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Aihio on valitun kappaleen ympärillä oleva suorakulmainen särmiö (lisättynä varalla).",
"Das Setup hat keine Operationen.":"Asetuksessa ei ole operaatioita.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Työkalu jyrsii ympyröissä, joiden keskipiste liikkuu uran suunnassa. Se ei ole koskaan kosketuksissa koko leveydeltään – tämä sallii suuret leikkaussyvyydet ja säästää jyrsintä ja karaa. Jyrsimen tulisi olla noin 60 % uran leveydestä.",
"Das Werkzeug schneidet die Fläche nicht":"Työkalu ei leikkaa pintaa",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Työkalu leikkaa valittuja pintoja kohti, kunnes se saavuttaa annetut työvarat.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Työkalu uppoaa pystysuoraan kuin pora, rivi riviltä, mallin pintaan lisättynä työvaralla. Leikkausvoima vaikuttaa karan suunnassa: sopii pitkille työkaluille, syville koloille ja vähemmän jäykille koneille. Työkalun on leikattava keskipisteen yli.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Työkalu välttää näitä pintoja annetut turvaetäisyydet huomioiden (kiinnityskynnet, ruuvipuristin).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Työkalu välttää näitä pintoja työstäessään lähellä olevia pintoja ja noudattaa turvaetäisyyksiä.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Ensimmäinen Esc peruu vain työkalun tai valinnan – ylimääräinen Esc ei sulje luonnosta",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Tämä ei ole reikä (pyöristys tai tappi) – napsauta reiän sisäseinämää.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Tämä ei ole reikä (lieriöpinta) – napsauta reiän seinämää.",
"Das ist keine WerkFab-Design-Datei.":"Tämä ei ole WerkFab-teematiedosto.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Tämä ei ole vino reuna – napsauta viistereunan molempia päitä.",
"Datei":"Tiedosto",
"Datei ist keine WerkFab-Einstellungsdatei.":"Tiedosto ei ole WerkFab-asetustiedosto.",
