"Datum/Uhrzeit":"Päivämäärä/kellonaika",
"Deaktivieren":"Poista käytöstä",
"Deckkraft":"Peittävyys",
"Deckkraft der Fenster":"Ikkunoiden peittävyys",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Halkaisija olisi nolla tai negatiivinen – pienennä etäisyyttä",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Kierrejyrsin ajaa täyteen materiaaliin: vapauta tappi ensin jyrsimällä (2D-ääriviiva tapin ulkopuolella kierteen syvyyteen asti).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Kappaleella ei ole ääriviivaa tällä tasolla.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Kappale otetaan verkkona näytön kolmioilla. Itse kappale säilyy; kappaleen myöhemmät muutokset eivät muuta verkkoa.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Kappale luetaan pystysuoran keskiakselinsa ympäri ja tallennetaan pitimen ääriviivana (osuudet) asiakirjan työkalukirjastoon.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Piste, jonka ympäri näkymä pyörii (vapaassa orbitissa). ”Hiiren osoittimen alla”: mallin kohta, jossa pyöritys alkaa.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Säde kasvaa tasaisesti jokaisen valitun reunan alusta loppuun. Reuna määrää, kumpi pää on alku – vaihda tarvittaessa.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Pinnan reuna on suljettu ketju: valinnalla ”jatkuva” säde kulkee kerran ympäri, ilman tätä valintaa jokaisella reunalla erikseen alkusäteestä loppusäteeseen.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Leikkaus ei osu mihinkään kappaleeseen – materiaalia ei poisteta.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Teksti on kommenttina tässä kohdassa ohjelmaa.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Ensimmäinen etäisyys mitataan pinnalta, joka osoittaa enemmän ylös (Z); toinen etäisyys tai kulma koskee toista pintaa. ”Vaihda puolet” kääntää tämän. Tangentiaalisesti liittyvät reunat tulevat mukaan.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Valittu kappale on aihio (esim. valu- tai taontaaihio). Sitä itseään ei työstetä.",
"Der große Geometriekern ist noch nicht geladen":"Täyttä geometriaydintä ei ole vielä ladattu",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Suurta geometriaydintä ladataan – tämä vaihe laskee itsestään uudelleen hetken kuluttua",
