"Design nicht gefunden.":"Mallia ei löytynyt.",
"Design, Farben, Symbole, Form und Schrift in einer Datei – zum Weitergeben oder für einen anderen Rechner":"Teema, värit, kuvakkeet, muoto ja kirjasin yhdessä tiedostossa – jaettavaksi tai toiselle tietokoneelle",
