"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Sorvaus: Z otsapinnan edessä, jossa revolveri indeksoituu. 0 = turvaetäisyys + 100 mm",
