"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Omia mittoja ja huomautuksia voi vetää arkilla hiirellä (mittaviivan etäisyys, johdeviivan kulma, kulmakaaren säde). Kaksi kulmaa napsauttamalla saat pituusmitan. Ympyrän reunan napsautus päällinäkymässä antaa halkaisijan (tai säteen). Kulma: ensin kärki, sitten yksi kulmapiste kummaltakin sivulta. Viiste: vinon reunan molemmat päät – tuloksena esim. 2×45°. Kunkin mitan perässä olevassa tekstikentässä on lisätieto, kuten ±0,1, H7 tai 4×.",
