"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Napsauta ensin siirrettävän kappaleen pintaa, sitten toisen kappaleen kohdepintaa. Kappaletta kierretään ja siirretään, kunnes ensimmäinen napsautuskohta on toisen päällä ja pinnat ovat vastakkain.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Napsauta ensin siirrettävän kappaleen reunaa, sitten toisen kappaleen kohdereunaa. Suorat reunat asettuvat yhteen (keskikohta keskikohtaan); ympyrän muotoisilla reunoilla – reikä ja tappi – akselit suunnataan samoiksi ja keskipisteet tuodaan yhteen.",
"Erst ein Setup anlegen.":"Luo ensin asetus.",
