"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Valitse ensin luonnos tai aputaso – silloin Ctrl+8 katsoo sitä kohtisuoraan.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Luo ensin kappale SUUNNITTELUssa tai lisää verkko (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Luo ensin kappale tilassa SUUNNITTELU.",
