"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Tasoja kappaleen päähän (kaksitaso, nelikulmio, kuusikulmio) pyörivällä päätyjyrsimellä Z-suunnassa. Avainväli = tason kaksinkertainen etäisyys pyörähdysakselista. X ja C liikkuvat yhdessä (napainterpolointi, Fanuc G12.1); ilman tätä mallipohjaa postprosessorissa tulostetaan lyhyitä X/C-askelia.",
