"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Luonnoksen suorat viivat, jotka eivät kuulu mihinkään profiiliin (myös apuviivat). Taivutus: viiva on taivutusvyöhykkeen keskikohta ja luonnos on siinä leikkuu – levyn suurin osa pysyy paikallaan, kaikki viivan toisella puolella kääntyy laippoineen mukana. Viiva koskee koko levyä. Painanne: viivan suuntainen jäykiste, poikkileikkaukseltaan ja päistään pyöreä; levy säilyttää paksuutensa.",
