"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Suljettu: kahden vierekkäisen reunan laipat ulottuvat kulman kulmanpuolittajaan ja jättävät siihen raon. Kulmavapautus sijaitsee siinä, missä taivutusvyöhykkeet leikkaavat – aukilevityksessä ja taivutetussa osassa. Myös kaarevan reunan laippa leikataan todellisessa kulmassa jiiriin (siinä ilman kulmavapautusta).",
"Geschlossene Kette {0}":"Suljettu ketju {0}",
