"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Tuoduilla kappaleilla ei ole suunnitteluhistoriaa, mutta niitä voi muokata edelleen (pyöristys, viiste, leikkaus …) ja käyttää CAM:ssa. Valinnalla ”Y-akseli ylös” ohjelmista, joissa Y osoittaa ylös, tulevat mallit asettuvat oikein.",
