"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Kustakin luonnoksesta ensimmäinen käyrä – avoin tai suljettu. Käyrät yhdistetään pintakalvolla (pinta ilman paksuutta).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Yksi tiedosto levyä kohti. Rata kulkee puolen leikkausuran (jyrsinnässä puolen jyrsimen) verran ääriviivan vieressä hukkapalassa; leikkaukset tulevat ennen oman osansa ulkoreunaa, ja jokainen ääriviiva alkaa sisääntulolla hukkapalasta. Päälle M3 (laser: M3 S…), pois M5, läpäisyaika G4:nä. Nollapiste on levyn vasen alakulma, jyrsinnässä Z0 on levyn yläpinta. Tarkista ohjelma koneella tai NC-simulaattorissa ennen käyttöä.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Kukin akseli erikseen: napsauta reunaa, kulmaa, pintaa tai reikää. Asettamattomat akselit otetaan aihion pisteestä.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Jokainen operaatio aliohjelmana (LBL) ohjelman lopussa, kutsutaan komennolla CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Jokainen luonnoksen ympyrä on reiän keskipiste. Poraus tehdään luonnoksen normaalia vastaan (materiaaliin).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Jokainen luonnoksen ympyrä toistetaan kiertäen keskipisteen (luonnoksen koordinaateissa) ympäri – ympyrä jakoympyrän säteen etäisyydellä tuottaa reikäympyrän.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Jokaisesta luonnoksen ympyrästä tulee ruudukko: etäisyydet luonnoksen X- ja Y-suunnassa (myös negatiiviset).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Valitse nyt piste toiselta sivulta.",
