"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Reuna {0}: laippa kaarevalla reunalla – sen reuna puristuu muovauksessa {1} % (ryppyjen vaara); avattu muoto on siinä kohdassa likimääräinen.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Reuna {0}: laippa kaarevalla reunalla – sen reuna venyy muovauksessa {1} % (halkeamien vaara); avattu muoto on siinä kohdassa likimääräinen.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Reuna {0}: laipan mitta {1} mm on pienempi kuin taivutus ({2} mm)",
