"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Reuna {0}: laippa risteää taivutusviivan kanssa – anna sen päättyä ennen taivutusta asetuksella „Etäisyys alku / loppu“",
