"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Reuna {0}: leikkaus on {1} mm taivutuksen vieressä (alle 2 × levyn paksuus) – se vääntyy taivutettaessa.",
