"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Reuna {0}{1}: laippa {2} mm on lyhyempi kuin 2 × levyn paksuus – tuskin taivutettavissa särmäyspuristimella.",
