"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Päästä korkki irti ja valitse ”Kalibroi nollapiste”. Kokeile sitten jokaista suuntaa: palkin pitäisi liikkua ja pysyä levossa harmaalla kuolleella alueella.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Korkin työntö = siirto, painaminen/vetäminen = zoomaus, kallistus ja kierto = mallin kierto. Luonnoksissa vain siirto ja zoomaus. SpaceMouse Pro/Enterprise: T, F, R = yläkuva, etukuva, oikea kuva. Jos mitään ei tapahdu: sulje 3Dconnexion-ajuri hetkeksi ja yhdistä uudelleen.",
