"Konturen außen und innen":"Ulko- ja sisäääriviivat",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Ääriviivat seuraavat tumman alueen reunaa. Keskiviiva kulkee viivojen keskellä – sopii kaiverruksiin ja viivapiirroksiin. ”Suorat, kaaret ja ympyrät” tunnistaa suorat reunat, terävät kulmat, pyöristykset ja ympyrät; ”Murtoviivat” seuraa kuvaa piste pisteeltä. Säädä mittakaava tarvittaessa jälkeenpäin toiminnolla ”Kalibroi pohjakuva” tai ”Skaalaa”.",
