"Kurven":"Käyrät",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Luonnoksen käyrät otsapinnalla (poikittain pyörähdysakseliin nähden) pyörivällä jyrsimellä Z-suunnassa (X ja C liikkuvat yhdessä; Fanuc: napainterpolointi G12.1). Avoimet käyrät jyrsitään edestakaisin. Syvyys otsapinnasta.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Pyörähdysakselin suuntaisen luonnoksen käyrät kierretään kehälle ja jyrsitään pyörivällä jyrsimellä, joka osoittaa kohti akselia (Z ja C liikkuvat yhdessä; Fanuc: sylinteri-interpolointi G7.1). Luonnoksen taso määrää kulman, jossa ääriviiva sijaitsee; vaakasuorat osuudet luonnoksessa muuttuvat kaariksi kappaleen ympäri. Syvyys ulkohalkaisijasta.",
"Kurzbefehl":"Pikanäppäin",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Lyhyet matkat (alhaalla pysymisen etäisyyteen asti) työkalu ajaa alhaalla siirtymäsyötöllä vetäytymiskorkeuden kautta kulkemisen sijaan – ilman törmäystarkistusta, joten pidä arvo pienenä.",
