"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Valitse materiaali asetuksessa kohdassa ”Aihio → Aihion materiaali”. Tiheydestä saadaan aihion paino, Vc on kovametallin ohjearvo; väri näkyy simulaatiossa.",
