"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Useat toisiinsa liittyvät reunat lasketaan yhdeksi matkaksi: säde kulkee ketjun alusta sen loppuun, tukipisteet ilmoitetaan %:na koko ketjun pituudesta. Tämän laskee suuri geometriaydin.",
