"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Tukipisteillä säde kulkee annettujen arvojen kautta (sijainti %:na reunan pituudesta). Tämän laskee suuri geometriaydin; ensimmäisellä kerralla sen lataus kestää muutaman sekunnin.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D-kosketusanturilla ei voi työstää",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Vertaa valmiiseen kappaleeseen: vihreä = mitassa, sininen = jäännösmateriaali, punainen = liian syvä",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Vie hiiri ääriviivan viereen (puoli määrää suunnan) · Esc lopettaa",
"Mit diesem Werkzeug kann nicht gefräst werden":"Tällä työkalulla ei voi jyrsiä",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Kierretapilla käytä vain sykliä „Kierteen tappaus“ – poraussykli katkaisisi sen",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Useilla syötöillä kierresyvyys jyrsitään vaiheittain, joista kukin poistaa suunnilleen yhtä paljon – säästää pieniä kierrejyrsimiä ja kovia materiaaleja. Tyhjä kierros ajaa viimeisen radan vielä kerran ilman syöttöä.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Valinnalla ”Poraussyklit” NC-ohjelmassa tulostetaan ohjauksen syklit (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), muuten auki kirjoitetut liikkeet.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Valinnalla „Säilytä alkuperäinen“ alkuperäisestä ja peilikuvasta tulee yksi verkko; peilitasolla olevat pisteet yhdistetään – avoimesta puoliskosta tulee näin suljettu kappale.",
