"Nichts getroffen – Kante, Ecke, Fläche oder Bohrung anklicken.":"Ei osumaa – napsauta reunaa, kulmaa, pintaa tai reikää.",
"Nichts getroffen – auf das Modell klicken.":"Ei osumaa – napsauta mallia.",
"Nichts gewählt – „Auswählen“ und im Modell anklicken.":"Ei valintaa – valitse „Valitse“ ja napsauta mallia.",
"Nichts gewählt – „Auswählen“, dann Flächen oder Kanten im Modell anklicken.":"Ei valintaa – valitse „Valitse“ ja napsauta sitten mallin pintoja tai reunoja.",
"Nichts geändert: Die Nachbarflächen schließen diese Lücke nicht – zusammengehörige Flächen gemeinsam wählen (z. B. Wand und Boden einer Tasche)":"Mitään ei muutettu: viereiset pinnat eivät sulje tätä rakoa – valitse yhteenkuuluvat pinnat yhdessä (esim. taskun seinä ja pohja)",
