"Noch kein Dreh-Setup: „Neues Setup“ → Bearbeitung „Drehen“ wählen.":"Ei vielä sorvausasetusta: „Uusi asetus“ → valitse työstöksi „Sorvaus“.",
"Noch kein Fräs-Setup vorhanden.":"Ei vielä jyrsinasetusta.",
"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"Kappaletta ei ole vielä valittu – siihen asti käytetään suhteellista särmiön kokoa.",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"Kappaletta ei ole vielä – mallinna ensin SUUNNITTELUSSA.",
"Noch keine Designs gespeichert.":"Malleja ei ole vielä tallennettu.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"Ei vielä kommentteja. Lisää muistiinpanoja mallista +-painikkeella.",
"Noch keine Operation":"Ei vielä operaatiota",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Ei vielä malleja. Malli tallentaa strategiat kaikkine asetuksineen (työkalu, leikkuutiedot, korkeudet, kierrokset, linkitys) käytettäväksi uudelleen muissa asetuksissa ja suunnitelmissa.",
"Noch keine Werkzeuge im Dokument.":"Asiakirjassa ei ole vielä työkaluja.",
"Noch keine. Geometrie wählen und oben unter ABHÄNGIGKEITEN ein Werkzeug anklicken.":"Ei vielä. Valitse geometria ja napsauta työkalua yllä kohdassa RAJOITTEET.",
