"Nur ASCII-Zeichen":"Vain ASCII-merkit",
"Nur Außenkonturen":"Vain ulkoääriviivat",
"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Vain ulkoääriviivat (tapit) onnistuvat ohjauksen syklinä",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Vain halkaisija (muoto kuten tällä työkalulla)",
"Nur Innenkonturen (Öffnungen)":"Vain sisäääriviivat (aukot)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Vain suorakulmaiset ja pyöreät taskut onnistuvat ohjauksen syklinä",
"Nur Skizze":"Vain luonnos",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Työstetään vain se, minkä suurempi jyrsin jätti kulmiin.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Seurataan vain ääriviivan kohtia, joihin suurempi jyrsin ei yltänyt (sisäkulmat, kapeat kohdat). Ilman sisään-/ulosajokaaria, pidikestegejä ja viimeistelykierroksia; korjaus tietokoneessa.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Vain siellä, minne vertailutyökalu ei yltänyt: tasaiset alueet rinnakkain, jyrkät alueet vesiviivana. Luettelon työkalulla myös sen muoto otetaan huomioon – esimerkiksi mitä torusjyrsin jättää uurteisiin.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Vain tasomaiset pinnat kelpaavat luonnostasoksi.",
"Nur ebene Flächen können extrudiert werden":"Vain tasomaisia pintoja voi pursottaa",
"Nur ebene Flächen lassen sich ersetzen":"Vain tasopintoja voi korvata",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Vain tasopintoja ja lieriöpintoja (reiät, tapit) voi siirtää",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Vain tasomaiset pinnat, jotka osoittavat ylös työkalua kohti (vaakasuorat tässä asetuksessa).",
"Nur für Außen-Drehmeißel":"Vain ulkosorvauskärjille",
"Nur in Operationen verwendete":"Vain operaatioissa käytetyt",
"Nur in diesem Projekt":"Vain tässä projektissa",
"Nur mit Korrektur „Im Rechner“.":"Vain korjauksella ”Tietokoneessa”.",
"Nur stärkste Achse":"Vain voimakkain akseli",
"Nut":"Ura",
"Nut angetrieben":"Ura pyörivällä työkalulla",
"Nut angetrieben (C-Achse)":"Ura pyörivällä työkalulla (C-akseli)",
"Nut liegt nicht am Teil":"Ura ei ole kappaleella",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Ura pyörähdysakselin suunnassa (esim. kiilaura) pyörivällä jyrsimellä, joka osoittaa kohti akselia; pääkara pitää kappaletta C-akselina. Uran leveys = jyrsimen Ø. Alku/loppu Z mallin Z:ssa; jos ura ulottuu otsapintaan, jyrsin ajaa sisään edestä, muuten se uppoaa alussa. Syvyys ulkohalkaisijasta.",
"Nutbreite bei Linien":"Uran leveys viivoilla",
