"Oder Skizze":"Tai luonnos",
"Offen (Laschen gekürzt)":"Avoin (laipat lyhennetty)",
"Offene Flächen":"Avoimet pinnat",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Avoimet reunat näytetään punaisina. ”Korjaa” sulkee reiät.",
"Offene Linie in einer Skizze wählen":"Valitse avoin viiva luonnoksesta",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Avoimet tai suljetut käyrät vedetään kohtisuoraan luonnokseen nähden – syntyy pinta (seinä ilman paksuutta). Toiminnolla ”Paksunna” tai ”Yhdistä” siitä tulee tilavuus.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Avoimet tai suljetut käyrät pyöräytetään akselin ympäri – syntyy pinta, ei tilavuutta.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Ilman omaa näppäintä käytössä on oletus „{0}“.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Ilman valintaa ”Mallinnettu” kierre vain esitetään (nopea). Mallinnettuna kierteen muoto leikataan todella, esim. 3D-tulostusta varten. Reikä M8:lle = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP sorvaus",
"Okuma OSP-M Fräsen":"Okuma OSP-M jyrsintä",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 eivät aja siellä konekoordinaatteihin (G53 kumoaa työkalun pituuskorjauksen) – vetäytyminen turvakorkeudelle, XY-referenssiajoa ei tulostettu",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: tasoitustoimintoa ei tulostettu (G5.1 on Fanuc) – aseta Hi-Cut/Super-NURBS koneella",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: korjaus+työkalu+terä (esim. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (kaikki toiminnot)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: kaikki toiminnot. Rust-ydin (truck, kokeellinen): perusmuodot, pursotus, pyöräytys, reikä, toisto, peilaus, siirto, skaalaus, yhdistelmä ja STEP-vienti – muut ominaisuudet merkitään ”ei vielä tuettu”.",
