"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Tasku kehälle luonnoksen suljetuista ääriviivoista, jotka ovat pyörimisakselin suuntaisesti (sisäiset ääriviivat jäävät saarekkeiksi). Luonnos kiedotaan halkaisijalle; akselia kohti osoittava käyttöinen vartiojyrsin tyhjentää sisältä ulospäin (Z ja C liikkuvat yhdessä; Fanuc: lieriöinterpolointi G7.1). Jyrsin sukeltaa ramppia pitkin sisimmän renkaan suuntaisesti.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Tasku otsapintaan luonnoksen suljetuista ääriviivoista (sisemmät ääriviivat jäävät saariksi) pyörivällä päätyjyrsimellä Z-suunnassa. Tyhjennys tehdään sisältä ulospäin; jyrsin uppoaa rampilla sisimmän radan suuntaisesti ja pysyy tason sisällä alhaalla. X ja C liikkuvat yhdessä (Fanuc: napainterpolointi G12.1). Syvyys otsapinnasta.",
