"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Laskee kaksi suljettua verkkoa oikeasti yhteen: sisällä olevat pinnat katoavat ja leikkausreunat verkotetaan uudelleen. Laskenta tehdään vain siellä, missä verkot voivat kohdata – siksi suuri verkko pienellä muutoksella on nopea. Jos kaksi suurta verkkoa on kokonaan päällekkäin, käytä ensin „Vähennä“.",
