"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Kietoo luonnoksen käyrät sylinterin ympärille: X pysyy X:nä, akseliin nähden poikittainen etäisyys muuttuu kaareksi kuvausympyrällä (kierto A). Luonnoksen on oltava A-akselin suuntainen, esim. tangenttitasolla. Jyrsintä tehdään kiinteällä syvyydellä kappaleen pinnan alla – kaiverruksiin, teksteihin ja uriin kappaleen ympäri.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Kuten 3D-ääriviiva, mutta työkalu liikkuu jatkuvasti alaspäin ilman portaita – ei uppoamisjälkiä jyrkillä seinämillä.",
