"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Lomita toisiinsa“ asettaa leikkuut naapureidensa rakoihin ja lahtiin sekä niiden leikkauksiin (ilman 90°:n kiertoa vain 180° käännettynä); etäisyys ei koskaan alitu. Ilman valintamerkkiä ne ovat riveissä ympäröivän suorakulmionsa mukaan. Valinnalla „Luonnos + kappaleet“ syntyy levyn paksuisia litteitä kappaleita, jotka voi leikata valmistuksessa 2D-ääriviivalla.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"„Sisä/Ulko“ vaatii suljetut ääriviivat – jyrsi avoimet käyrät asetuksella „Käyrällä“",
